"""Build the self-contained, version-controlled Colab notebook from its sources."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
cells = []
def md(text): cells.append({'cell_type':'markdown','metadata':{},'source':text.splitlines(True)})
def code(text): cells.append({'cell_type':'code','metadata':{},'execution_count':None,'outputs':[], 'source':text.splitlines(True)})
md('''# ByteCore Phase 19 — phone-size research experiment\n\n**Run all cells in a fresh free Colab T4 runtime** (Runtime → Change runtime type → T4 GPU). This is a standalone notebook; no repository clone is required. It embeds its source and writes it into `/content/phase19_standalone`.\n\n**Reality check:** this starts a new model from random weights and does not inherit the Phase 18 benchmark results. Four hours cannot guarantee fluency, coding, search routing, Minecraft or editing. Evaluate actual outputs below. T4 lacks native BF16 and FlashAttention 2; CUDA FP16 autocast/gradient scaling and PyTorch's supported SDPA kernel are used. The phone target refers to weight size, not RAM, speed, or a complete mobile app. ONNX needs an appropriate mobile runtime.\n\nThe default 47 minutes per stage reserves overhead; this is not four 60-minute stages. Start-to-training deadline is 3h35m, with remaining time for upload/export/evaluation, but Colab/network can interrupt earlier. Each 15-minute checkpoint is synchronous and may be late for a long step/upload; failures stop training. The private HF model repository is created if needed. Resume fetches the highest stage/step and restores optimizer, scaler, elapsed stage time and RNG. Only load checkpoints from a trusted repository (PyTorch pickle). Session memory and cache are not persisted; rebuild the same cache or supply the same data on resume. You must have HF account/repository write access.\n\nDatasets may be gated, removed, mislabeled or unavailable; metadata is not legal advice. The notebook refuses unknown/non-permissive dataset licenses and does not fake missing real data. If a group is empty, add a local UTF-8 text file with cleared usage rights as directed below. Synthetic examples are explicitly labeled; Minecraft isn't executed, DDG requires network, grammar and code rewards are very weak proxies. Never execute model-generated code or Minecraft calls without an actual sandbox/authorization.\n''')
code('''import os, time, sys\nSESSION_STARTED = time.time()\nSESSION_DEADLINE = SESSION_STARTED + 3*3600 + 35*60\nprint('Session budget starts now. Check GPU:')\n!nvidia-smi\n''')
md('## 1. Install dependencies\nColab supplies PyTorch. Package installation and model export use network and can take several minutes.\n')
code('''%pip -q install "datasets>=3,<5" "huggingface_hub>=0.25,<2" "ddgs>=9,<10" "onnx>=1.16,<2" tqdm\n''')
md('## 2. Unpack the embedded, auditable source\nThe following cells write the same Python modules that accompany the notebook in the repository.\n')
code('''from pathlib import Path\nROOT = Path('/content/phase19_standalone')\nROOT.mkdir(parents=True, exist_ok=True)\nos.chdir(ROOT)\nsys.path.insert(0, str(ROOT))\n''')
for name in ['__init__.py','dataset_discovery.py','preprocess.py','hf_upload.py','phone_model.py','tools.py','train.py','evaluate.py']:
    content = (ROOT/'notebook'/name).read_text(encoding='utf8')
    code(f"Path('notebook').mkdir(exist_ok=True)\nPath('notebook/{name}').write_text({content!r}, encoding='utf8')\n")
md('''## 3. Credentials and experiment settings\nUse a **write-scoped** HF token entered privately via the input prompt; do not paste it into code or publish a saved notebook with secrets. Set `repo_id` to your own account/repository. Resume trusts uploaded pickle data. Batch size 1 × accumulation 32 defaults to effective 32; increase micro batch only if T4 VRAM allows. Stage lengths may be changed for experiments, but four 60-minute stages do not fit a 4-hour session with overhead.\n''')
code('''from getpass import getpass\nimport torch, random\nfrom notebook.phone_model import Config, PhoneLM\nfrom notebook.hf_upload import latest_checkpoint, load_checkpoint\nHF_TOKEN = getpass('Hugging Face write token: ')\nREPO_ID = input('Private model repo (username/repo): ').strip()\nif not HF_TOKEN or '/' not in REPO_ID: raise ValueError('A token and username/repo are required')\nprint('GPU:', torch.cuda.get_device_name(0) if torch.cuda.is_available() else 'CPU (T4 strongly recommended)')\nrandom.seed(19); torch.manual_seed(19)\ncfg = Config()\nmodel = PhoneLM(cfg)\nprint('Parameters:', sum(p.numel() for p in model.parameters()), '; raw FP16 MB:', sum(p.numel() for p in model.parameters())*2/1e6)\ncheckpoint_path = latest_checkpoint(REPO_ID, HF_TOKEN)\nresume = load_checkpoint(checkpoint_path) if checkpoint_path else None\nprint('Resume:', checkpoint_path or 'starting from scratch')\n''')
md('''## 4. Discover and cache real datasets\nResults include dataset IDs, language, declared license, and size where exposed. The preselected `pierreguillou/bert-base-cased-pt-br` is a **model**, not a dataset; `maritaca-ai/en2ptbridge` is inspected as a candidate, not assumed to exist or be useful. OASST chat messages are not falsely relabeled as tool trajectories. Candidate datasets are sampled via streaming and hard per-group limits; unknown or non-permissive licenses are skipped. Review `data_cache/manifest.json` and source terms yourself.\n''')
code('''from notebook.dataset_discovery import discover, collect\nfrom notebook.preprocess import synthetic\nreports = discover(limit=5)\ngroups = collect(max_rows=4000, max_bytes=8_000_000)\ngroups.update(synthetic())\nprint({k: len(v) for k,v in groups.items()})\n''')
md('''### Missing real data?\nIf `pt`, `en`, or `code` is empty, upload or write a UTF-8 text file per group in `/content/phase19_standalone/manual_data/pt.txt`, `en.txt`, or `code.txt` and rerun the next cell. One example per line. You are responsible for permission and license compatibility; report provenance separately. The trainer refuses empty groups rather than quietly substituting synthetic rows.\n''')
code('''from notebook.train import check_groups\nfor kind in ('pt', 'en', 'code'):\n    path = ROOT / 'manual_data' / (kind+'.txt')\n    if path.exists():\n        with path.open(encoding='utf8') as f:\n            groups[kind].extend(line.strip()[:4096] for line in f if line.strip())\nprint({k: len(v) for k,v in groups.items()})\ncheck_groups(groups)\n''')
md('''## 5. Train and upload\nStages use 50/30/20 pt/en/code, 50/30/20 code/Minecraft/pt, and 40/30/30 ReAct/search/code. The last stage alternates supervised edits with sparse sampled REINFORCE and weak, non-executing rewards. Freeze counts are 0/6/8/8 blocks. Sequences are UTF-8 bytes truncated to 1024. If checkpoint upload fails, training raises; the local snapshot remains in `checkpoints/` but is lost if the runtime disappears.\n''')
code('''from notebook.train import train\ncompleted = train(model, groups, HF_TOKEN, REPO_ID, SESSION_DEADLINE,\n                  stage_seconds=47*60, upload_seconds=15*60, micro_batch=1, accumulation=32, resume=resume)\nprint('All four stages completed:', completed)\n''')
md('''## 6. Evaluate actual free-running outputs\nThese six tiny probes are not statistically valid benchmarks, and passing heuristics do not establish correctness. Code is parsed, never executed; Minecraft is syntax-checked only. Memory is supplied in the prompt by the host, not stored inside the network. Search is checked for a generated call, not a real DDG request. Model outputs can fail every probe.\n''')
code('''from notebook.evaluate import evaluate\nresults = evaluate(model)\nfor row in results:\n    print('\\n', row['case'], 'PASS' if row['pass'] else 'FAIL', '\\n', repr(row['output']))\nprint('Probes passed:', sum(x['pass'] for x in results), '/', len(results))\n''')
md('''## 7. Export and download\nFP16 weights are exported separately from large resumable optimizer checkpoints. ONNX exports FP32 for compatibility and may be ~2× larger; it is an optional runtime representation, not a verified phone app. The model is moved to CPU by export. Verify numerical and mobile-runtime behavior on your target device before deployment.\n''')
code('''import json, shutil, zipfile\nfrom dataclasses import asdict\nfrom notebook.phone_model import export_onnx\nout = ROOT/'phone_export'; out.mkdir(exist_ok=True)\ntorch.save({k:v.detach().cpu().half() for k,v in model.state_dict().items()}, out/'phone_fp16.pt')\n(out/'config.json').write_text(json.dumps(asdict(cfg), indent=2))\nshutil.copytree(ROOT/'notebook', out/'notebook', dirs_exist_ok=True, ignore=shutil.ignore_patterns('__pycache__', 'build_notebook.py'))\ntry:\n    export_onnx(model, str(out/'phone_fp32.onnx'))\n    print('ONNX export succeeded:', (out/'phone_fp32.onnx').stat().st_size/1e6, 'MB')\nexcept Exception as exc:\n    print('ONNX export FAILED:', type(exc).__name__, str(exc))\n# Download weights/source separately from ONNX to keep the primary artifact small.\nwith zipfile.ZipFile(ROOT/'phone_model_fp16.zip', 'w', compression=zipfile.ZIP_STORED) as z:\n    for path in out.rglob('*'):\n        if path.is_file() and path.suffix != '.onnx': z.write(path, path.relative_to(out))\nprint('FP16 bundle MB:', (ROOT/'phone_model_fp16.zip').stat().st_size / 1e6)\nfrom google.colab import files\nfiles.download(str(ROOT/'phone_model_fp16.zip'))\n# Optional: uncomment to download the larger ONNX model separately.\n# files.download(str(out/'phone_fp32.onnx'))\n''')
# Avoid colliding with Jupyter's installed ``notebook`` package in Colab.
for i, cell in enumerate(cells):
    cell['id'] = f'phase19-{i:03d}'
    if cell['cell_type'] == 'code':
        src = ''.join(cell['source'])
        for old, new in [('notebook.', 'phase19.'), ("Path('notebook')", "Path('phase19')"),
                         ("Path('notebook/", "Path('phase19/"), ("ROOT/'notebook'", "ROOT/'phase19'"),
                         ("out/'notebook'", "out/'phase19'")]:
            src = src.replace(old, new)
        cell['source'] = src.splitlines(True)
nb={'cells':cells,'metadata':{'colab':{'name':'phase19_colab.ipynb'},'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.11'}},'nbformat':4,'nbformat_minor':5}
(ROOT/'notebook'/'phase19_colab.ipynb').write_text(json.dumps(nb,ensure_ascii=False,indent=1)+'\n',encoding='utf8')
